          { name: "项目通过完工评价且完工日期在项目备案证建设期内", required: true, weight: 3, autoMatch: "projectStatus", rule: v => v === "已完工" ? true : v === "不清楚" ? undefined : false, description: "细则第六条专题一各方向基本条件：项目通过完工评价且完工日期在项目备案证建设期内（快技改方向另要求首次备案计划开工日期后一个顺延年内完工）；表单拟申报项目实施状态选「已完工」即满足，完工日期是否在建设期内需人工核验", basis: { name: "细则第六条专题一", url: "https://www.zhuhai.gov.cn/sjb/zw/zcwj/content/post_3919214.html" }, evidence: "项目完工评价材料（完工日期与备案证建设期对照）" },
          { name: "固投设备奖补门槛：设备投资 ≥200 万元（不含税）", required: true, weight: 2, description: "细则第六条专题一：常规技改方向固投 ≥500 万且设备 ≥200 万（不含税）；小技改方向固投 <500 万但设备 ≥200 万——设备投资 ≥200 万为固投设备奖补各方向共同最低门槛（大技改设备 ≥3 亿、快技改 ≥3000 万）；表单投资额档位为项目总投资口径，设备投资需人工核验", basis: { name: "细则第六条专题一", url: "https://www.zhuhai.gov.cn/sjb/zw/zcwj/content/post_3919214.html" }, evidence: "设备购置明细与发票（不含税、发票与付款从小）" }
